function makeLedger(start) {
  let balance = start;
  const log = [];
  return {
    deposit: (n) => {
      balance += n;
      log.push(n);
      return balance;
    },
    withdraw: (n) => {
      if (n > balance) return balance;
      balance -= n;
      log.push(-n);
      return balance;
    },
    balance: () => balance,
    history: () => log.slice(),
  };
}

function runLedger(start, moves) {
  const ledger = makeLedger(start);
  for (const move of moves) {
    if (move >= 0) ledger.deposit(move);
    else ledger.withdraw(-move);
  }
  const taken = ledger.history();
  taken.push(999);
  return [ledger.balance(), ledger.history()];
}

